package io.github.toolazytoname.xiaohei;
public final class AuthorizationTierPolicyTest { public static void main(String[] a){int allow=0,deny=0;for(AuthorizationTierPolicy.Tier t:AuthorizationTierPolicy.Tier.values())for(ToolCatalog.Audience u:ToolCatalog.Audience.values()){AuthorizationTierPolicy.Result r=AuthorizationTierPolicy.authorize(t,u);if(r.modelCalls!=0||r.executionCalls!=0)throw new AssertionError();if(r.decision==AuthorizationTierPolicy.Decision.ALLOW)allow++;else deny++;}if(AuthorizationTierPolicy.authorize(null,ToolCatalog.Audience.ANDROID_GATEWAY).decision!=AuthorizationTierPolicy.Decision.DENY_MISSING)throw new AssertionError();System.out.println("PASS AuthorizationTierPolicyTest allow="+allow+" cross_tier="+deny+" root_unimplemented=true execution_paths=0");}}
